<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,type Account} from '../api'
import {money,time,outcomeLabel,anomalyLabel,type Order,type Reconciliation} from './orders/types'
import {paymentStatus} from './orders/offline-payment.mjs'
import {fulfillmentLabel,remaining,shippingQuantity} from './orders/fulfillment.mjs'
import OrderBenefitsSummary from '../shared/OrderBenefitsSummary.vue'
import FulfillmentPanel from './orders/FulfillmentPanel.vue'
import OrderActionDialog from './orders/OrderActionDialog.vue'
import {orderActions,actionLabels,pendingActions,actionPermission,type OrderAction} from './orders/order-actions.mjs'
import {isPointsOrder,orderSettlementValue,paymentMethodLabel} from '../shared/order-settlement.mjs'
import './orders/orders.css'
const props=defineProps<{account:Account}>(),route=useRoute()
const order=ref<Order|null>(null),loading=ref(true),error=ref(''),notice=ref(''),resultAnomaly=ref(false)
const action=ref<OrderAction|null>(null),resumeRecord=ref<Reconciliation|null>(null)
const canConfirm=computed(()=>props.account.permissionCodes.includes('payment.offline.confirm'))
const isPoints=computed(()=>isPointsOrder(order.value)),isOffline=computed(()=>order.value?.paymentMethod==='OFFLINE')
const recoveries=computed(()=>order.value?pendingActions(props.account.accountId,order.value.orderId,sessionStorage).filter(a=>props.account.permissionCodes.includes(actionPermission(a))):[])
const actions=computed(()=>orderActions(order.value,props.account.permissionCodes))
let generation=0
async function load(){const current=++generation;loading.value=true;error.value='';try{const result=await api<Order>(`/orders/${encodeURIComponent(String(route.params.orderId))}`);if(current===generation)order.value=result}catch(e){if(current===generation){order.value=null;error.value=e instanceof Error?e.message:'订单读取失败。'}}finally{if(current===generation)loading.value=false}}
function resume(record:Reconciliation){resumeRecord.value=record;action.value='receipt'}
function openAction(value:OrderAction){resumeRecord.value=null;action.value=value}
watch(()=>`${route.params.orderId}:${props.account.accountId}`,()=>{action.value=null;resumeRecord.value=null;order.value=null;notice.value='';void load()})
onMounted(load);onUnmounted(()=>generation++)
</script>
<template>
  <section class="page-content orders-page">
    <header class="page-heading"><div><RouterLink to="/orders" class="text-link">返回订单列表</RouterLink><h1 style="margin-top:16px">订单详情</h1><p>{{isPoints?'积分兑换成功后直接结算；每个订单项独立履约。':'订单收款与每项履约独立记录；确认收款后才能发货或核销。'}}</p></div><button class="secondary-button" :disabled="loading" @click="load">刷新订单状态</button></header>
    <p v-if="loading" role="status" class="loading-inline">正在读取订单详情…</p>
    <div v-if="error" class="notice" role="alert">{{ error }} <button v-if="!order" class="text-button" @click="load">重新加载</button></div>
    <p v-if="notice" role="status" :class="resultAnomaly ? 'order-warning' : 'order-success'">{{ notice }}</p>
    <template v-if="order && !loading"><section v-if="actions.length||recoveries.length" class="panel order-section"><div class="fulfillment-actions"><button v-for="a in recoveries" :key="'recovery-'+a" class="secondary-button" @click="openAction(a)">核查{{actionLabels[a]}}结果</button><button v-for="a in actions" :key="a" class="secondary-button" @click="openAction(a)">{{actionLabels[a]}}</button></div></section><section class="panel order-section"><h2>订单归属与履约</h2><p>订单来源：{{order.dining?'餐饮联盟':'普通商城'}}</p><p v-if="order.dining">餐饮店：{{order.dining.name}} · 桌号 {{order.dining.tableNumber}}<br>配送到：{{order.dining.address}}</p><p v-if="order.fulfillmentWarehouse">履约仓库：{{order.fulfillmentWarehouse.name}} · {{order.fulfillmentWarehouse.id}}</p><p>履约前置仓：{{order.storeName||'平台订单'}} · {{({PICKUP:'到店自提',DELIVERY:'配送到家',EXPRESS:'快递发货'} as Record<string,string>)[order.deliveryMode||'']||'按商品履约'}}</p></section>
      <section class="panel order-section"><h2>{{ isPoints ? paymentStatus(order) : order.payableFen===0 && order.status==='PAID' && !order.receipts?.some(r => r.anomaly?.status==='OPEN') ? '零现金订单已结算' : paymentStatus({ ...order, paymentReviewStatus: order.receipts?.some(r => r.anomaly?.status === 'OPEN') ? 'ANOMALY' : order.paymentReviewStatus }) }}</h2><dl class="order-facts"><div><dt>订单号</dt><dd>{{ order.orderNo }}</dd></div><div><dt>支付方式</dt><dd>{{isPoints?paymentMethodLabel(order):order.payableFen === 0 ? '零现金结算' : paymentMethodLabel(order)}}</dd></div><div><dt>履约进度</dt><dd>{{ order.status === 'PAID' ? fulfillmentLabel(order.fulfillmentStatus) : '确认收款后开始' }}</dd></div><div><dt>{{isPoints?'已扣兑换积分':'应付金额'}}</dt><dd class="order-money">{{orderSettlementValue(order)}}</dd></div><div><dt>创建时间</dt><dd>{{ time(order.createdAt) }}</dd></div><div v-if="!isPoints"><dt>付款截止</dt><dd>{{ time(order.expiresAt) }}</dd></div><div><dt>{{ order.status === 'CLOSED' ? '关闭时间' : isPoints ? '积分结算时间' : order.payableFen===0 ? '零现金结算时间' : '确认收款时间' }}</dt><dd>{{ time(order.status === 'CLOSED' ? order.closedAt : order.paidAt) }}</dd></div></dl><p v-if="order.status === 'CLOSED' && !isPoints" class="order-warning">原单已关闭。若发现到账，只登记异常资金，不恢复订单；按异常流程处理。</p></section>
      <section class="panel order-section"><h2>{{isPoints?'订单项与兑换积分':'订单项与金额'}}</h2><div class="table-wrap" tabindex="0" aria-label="订单项，可横向滚动"><table><thead><tr><th>商品 / SKU</th><th>履约方式</th><th>数量</th><th>履约进度</th><th>{{isPoints?'积分单价':'商品金额'}}</th><th>{{isPoints?'兑换积分':'优惠后金额'}}</th></tr></thead><tbody><tr v-for="line in order.items" :key="line.orderLineId"><td>{{ line.name }}<small class="order-muted">{{ line.skuCode }}</small></td><td>{{ line.fulfillmentKind === 'SHIP' ? (({PICKUP:'到店自提',DELIVERY:'配送到家',EXPRESS:'快递发货'} as Record<string,string>)[order.deliveryMode||'']||'快递') : '到店核销' }}</td><td>{{ line.quantity }} {{ line.saleUnit }}<small v-if="line.fulfillmentKind==='SHIP'" class="order-muted"><template v-if="shippingQuantity(line)">已完成售后退回 {{shippingQuantity(line)!.refunded}} {{line.saleUnit}}<template v-if="!order.shipment&&!['COMPLETED','REFUNDED'].includes(line.fulfillment?.status||'')"> · {{['DELIVERY','PICKUP'].includes(order.deliveryMode||'')?'待交付':line.fulfillment?.status==='AFTER_SALE'?'未发':'待发'}} {{shippingQuantity(line)!.remaining}} {{line.saleUnit}}</template></template><span v-else>发货数量待核查</span></small></td><td><strong>{{ line.fulfillment?.status ? fulfillmentLabel(line.fulfillment.status) : '待履约' }}</strong><small v-if="line.fulfillmentKind === 'REDEEM'" class="order-muted">已核销 {{ line.fulfillment?.redeemedQuantity || 0 }} · 剩余 {{ remaining(line) }}<br>有效至 {{ line.fulfillment?.validUntil || '待确认' }}</small></td><td>{{isPoints?`${line.pointsUnitPrice??'待核查'} 积分`:money(line.goodsAmountFen)}}</td><td>{{isPoints?`${line.pointsTotal??'待核查'} 积分`:money(line.payableFen)}}</td></tr></tbody></table></div><p v-if="isPoints">本单已扣 {{order.exchangePoints}} 积分，现金结算为 0；快递配送已含，不产生消费金额或消费奖励积分。</p><p v-else>商品 {{ money(order.goodsTotalFen) }} + 运费 {{ money(order.shippingFeeFen) }} − 券 {{ money(order.couponDiscountFen) }} − 积分 {{ money(order.pointsDiscountFen) }} = 应付 {{ money(order.payableFen) }}</p><p v-if="order.address">收货：{{ order.address.recipientName }} · {{ order.address.phone }}<br>{{ order.address.province }}{{ order.address.city }}{{ order.address.district }}{{ order.address.detail }}</p><p v-else>本单无需快递地址。</p></section>
      <section v-if="account.permissionCodes.includes('aftersale.read')" class="panel order-section"><div class="fulfillment-heading"><div><h2>售后申请与退款</h2><p>{{isPoints?'按订单项审核退积分申请，经授权确认数量与权益；取消申请沿售后审核处理。':'按订单项审核申请、核对实际退款凭证并由另一名授权人员确认。'}}</p></div><RouterLink :to="{ path: '/aftersales', query: { orderNo: order.orderNo } }" class="secondary-button">查看本单售后</RouterLink></div></section>
      <OrderBenefitsSummary v-if="order.orderBenefits" :summary="order.orderBenefits" :order-kind="order.orderKind" />
      <section v-if="order.localDeliveryEvents?.length" class="panel order-section"><h2>备货与交付记录</h2><p v-if="(order.localDeliveryEventCount||0)>20">共{{order.localDeliveryEventCount}}条，展示最近20条。</p><article v-for="record in order.localDeliveryEvents" :key="record.eventId" class="order-report"><strong>{{({PREPARE:'备货完成',DISPATCH:'开始配送',COMPLETE:'交付完成'} as Record<string,string>)[record.action]||record.action}}</strong><p>{{time(record.occurredAt)}} · {{record.actorName}}</p><p>{{record.note||'未填写备注'}}</p></article></section>
      <FulfillmentPanel v-if="!['DELIVERY','PICKUP'].includes(order.deliveryMode||'')" :account="account" :order="order" @updated="order = $event" @operate="openAction" />
      <section v-if="order.items.some(line => line.fulfillmentKind === 'REDEEM')" class="panel order-section"><div class="fulfillment-heading"><div><h2>到店核销</h2><p>每个核销商品有独立凭证；PC 使用扫码枪或手工输码，不读取用户端凭证明文。</p></div><RouterLink v-if="account.permissionCodes.includes('fulfillment.redeem')" to="/redemptions" class="primary-button">打开核销台</RouterLink></div><article v-for="line in order.items.filter(item => item.fulfillmentKind === 'REDEEM')" :key="line.orderLineId" class="order-report"><strong>{{ line.name }}</strong><p>购买 {{ line.quantity }} · 已核销 {{ line.fulfillment?.redeemedQuantity || 0 }} · 剩余 {{ remaining(line) }} · {{ fulfillmentLabel(line.fulfillment?.status) }}</p><p>有效至 {{ line.fulfillment?.validUntil || '待确认' }}</p><small class="order-muted">凭证须由顾客在小程序订单详情出示；店员输入核销台后实时核验。</small></article></section>
      <section v-if="isOffline && order.payableFen > 0" class="panel order-section"><h2>付款说明与用户报告</h2><p class="order-instructions">{{ order.paymentInstructions?.instructions || '下单时未配置付款说明。' }}</p><p v-if="!order.paymentReports?.length">用户尚未报告付款。</p><article v-for="report in order.paymentReports" :key="report.reportId" class="order-report"><strong>用户报告 · {{ time(report.reportedAt) }}</strong><p>{{ report.note }}</p><small class="order-muted">此记录为用户自述，不能代替实际到账流水。</small></article></section>
      <section v-if="!isPoints" class="panel order-section"><h2>实际到账记录</h2><p v-if="(order.receiptCount || 0) > 50" class="order-note">共 {{ order.receiptCount }} 条，当前展示最近 50 条。更早记录需由有权限的人员查询审计日志和资金存档核查。</p><p v-if="!order.receipts?.length">{{order.payableFen===0 ? '零现金订单由系统结算，不产生资金到账凭证；履约以服务端结算状态为准。' : '尚无实际到账凭证。确认收款前不能履约。'}}</p><article v-for="receipt in order.receipts" :key="receipt.receiptId" class="order-report"><dl class="order-facts"><div><dt>收款账户</dt><dd>{{ receipt.merchantAccountId }}</dd></div><div><dt>外部流水号</dt><dd>{{ receipt.externalTradeNo }}</dd></div><div><dt>实际金额</dt><dd>{{ money(receipt.amountFen) }}</dd></div><div><dt>实际到账时间</dt><dd>{{ time(receipt.paidAt) }}</dd></div><div><dt>结算时间</dt><dd>{{ time(receipt.appliedAt) }}</dd></div><div><dt>处理状态</dt><dd>{{ receipt.anomaly?.status === 'OPEN' ? `异常 · ${anomalyLabel(receipt.anomaly.reason)}` : receipt.appliedAt ? '已结算' : '待处理' }}</dd></div></dl></article><h3 v-if="order.confirmations?.length">操作员核对记录</h3><p v-if="(order.confirmationCount || 0) > 50" class="order-note">共 {{ order.confirmationCount }} 条，当前展示最近 50 条。</p><article v-for="record in order.confirmations" :key="record.reconciliationId" class="order-report"><p>{{ record.actorName || '授权操作员' }} · {{ time(record.authorizedAt || record.createdAt) }} · {{ outcomeLabel(record.outcome) }}</p><p>{{ record.externalTradeNo }} · {{ money(record.amountFen) }}<br>{{ record.note || '未填写备注' }}</p><button v-if="canConfirm && record.actorId === props.account.accountId && record.authorizedAt && ['AUTHORIZED', 'FAILED', 'PENDING'].includes(record.outcome || '')" class="secondary-button" :disabled="loading" @click="resume(record)">重试这条核对记录</button></article></section>
    </template>
    <OrderActionDialog :account="account" :order-id="order?.orderId||''" :action="action" :reconciliation="resumeRecord" @close="action=null;resumeRecord=null" @updated="order=$event" @notice="notice=$event"/>
  </section>
</template>
